<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Validation\Rule;
class SalesController extends Controller {
 public function workspace():JsonResponse {return response()->json(['customers'=>DB::table('customers')->orderBy('name')->get(),'reps'=>DB::table('sales_representatives')->orderBy('name')->get(),'articles'=>DB::table('articles')->orderBy('name')->get()->map(function($x){$x->sizes=DB::table('article_sizes')->where('article_id',$x->id)->orderBy('sort_order')->get();return $x;}),'pos'=>DB::table('customer_pos as p')->join('customers as c','c.id','=','p.customer_id')->join('sales_representatives as r','r.id','=','p.sales_rep_id')->select('p.*','c.name as customer_name','r.name as rep_name')->latest('p.id')->get()->map(function($x){$x->lines=DB::table('customer_po_lines as l')->join('articles as a','a.id','=','l.article_id')->where('l.customer_po_id',$x->id)->select('l.*','a.code as article_code','a.name as article_name')->get();return $x;}),'orders'=>DB::table('sales_orders as s')->join('customers as c','c.id','=','s.customer_id')->join('sales_representatives as r','r.id','=','s.sales_rep_id')->select('s.*','c.name as customer_name','r.name as rep_name')->latest('s.id')->get(),'invoices'=>DB::table('sales_invoices as i')->join('customers as c','c.id','=','i.customer_id')->join('sales_representatives as r','r.id','=','i.sales_rep_id')->select('i.*','c.name as customer_name','r.name as rep_name')->latest('i.id')->get(),'receipts'=>DB::table('customer_receipts as p')->join('customers as c','c.id','=','p.customer_id')->join('sales_representatives as r','r.id','=','p.sales_rep_id')->select('p.*','c.name as customer_name','r.name as rep_name')->latest('p.id')->get(),'commissions'=>DB::table('receipt_allocations as a')->join('customer_receipts as r','r.id','=','a.receipt_id')->join('sales_invoices as i','i.id','=','a.invoice_id')->join('sales_representatives as rep','rep.id','=','r.sales_rep_id')->join('customers as c','c.id','=','r.customer_id')->select('a.*','r.number as receipt_number','r.receipt_date','i.number as invoice_number','i.total as invoice_total','rep.name as rep_name','c.name as customer_name')->latest('a.id')->get()]);}
 public function storeCustomer(Request $r):JsonResponse {$d=$r->validate(['code'=>'required|max:30|unique:customers,code','name'=>'required|max:160','tin'=>'nullable|max:40','phone'=>'nullable|max:30','address'=>'nullable|max:255','credit_days'=>'required|integer|min:0|max:365','credit_limit'=>'required|numeric|min:0']);$id=DB::table('customers')->insertGetId($d+['status'=>'active','created_at'=>now(),'updated_at'=>now()]);return response()->json(DB::table('customers')->find($id),201);}
 public function updateCustomer(Request $r,int $id):JsonResponse {$d=$r->validate(['code'=>['required','max:30',Rule::unique('customers','code')->ignore($id)],'name'=>'required|max:160','tin'=>'nullable|max:40','phone'=>'nullable|max:30','address'=>'nullable|max:255','credit_days'=>'required|integer|min:0|max:365','credit_limit'=>'required|numeric|min:0','status'=>'required|in:active,inactive']);DB::table('customers')->where('id',$id)->update($d+['updated_at'=>now()]);return response()->json(DB::table('customers')->find($id));}
 public function storeRep(Request $r):JsonResponse {$d=$r->validate(['code'=>'required|max:30|unique:sales_representatives,code','name'=>'required|max:160','manager_name'=>'nullable|max:160','channel'=>'required|in:head_office,direct_sales,future_channel','default_commission_rate'=>'required|numeric|min:0']);$id=DB::table('sales_representatives')->insertGetId($d+['status'=>'active','created_at'=>now(),'updated_at'=>now()]);return response()->json(DB::table('sales_representatives')->find($id),201);}
 public function updateRep(Request $r,int $id):JsonResponse {$d=$r->validate(['code'=>['required','max:30',Rule::unique('sales_representatives','code')->ignore($id)],'name'=>'required|max:160','manager_name'=>'nullable|max:160','channel'=>'required|in:head_office,direct_sales,future_channel','default_commission_rate'=>'required|numeric|min:0','status'=>'required|in:active,inactive']);DB::table('sales_representatives')->where('id',$id)->update($d+['updated_at'=>now()]);return response()->json(DB::table('sales_representatives')->find($id));}
 public function storeArticle(Request $r):JsonResponse {$d=$r->validate(['code'=>'required|max:30|unique:articles,code','name'=>'required|max:160','category'=>'required|max:80','set_name'=>'required|max:80','selling_price'=>'required|numeric|min:0','commission_rate'=>'required|numeric|min:0','sizes'=>'required|array|min:1','sizes.*.label'=>'required|max:30','sizes.*.pieces'=>'required|numeric|gt:0']);$id=DB::transaction(function()use($d){$pieces=collect($d['sizes'])->sum('pieces');$id=DB::table('articles')->insertGetId(['code'=>$d['code'],'name'=>$d['name'],'category'=>$d['category'],'set_name'=>$d['set_name'],'pieces_per_set'=>$pieces,'selling_price'=>$d['selling_price'],'commission_rate'=>$d['commission_rate'],'status'=>'active','created_at'=>now(),'updated_at'=>now()]);foreach($d['sizes'] as $i=>$s)DB::table('article_sizes')->insert(['article_id'=>$id,'size_label'=>$s['label'],'pieces_per_set'=>$s['pieces'],'sort_order'=>$i+1,'created_at'=>now(),'updated_at'=>now()]);return $id;});return response()->json(DB::table('articles')->find($id),201);}
 public function storePo(Request $r):JsonResponse {$d=$r->validate(['customer_id'=>'required|exists:customers,id','sales_rep_id'=>'required|exists:sales_representatives,id','customer_po_reference'=>'nullable|max:80','po_date'=>'required|date','sale_type'=>'required|in:cash,credit,mixed','lines'=>'required|array|min:1','lines.*.article_id'=>'required|exists:articles,id','lines.*.sets'=>'required|numeric|gt:0']);$po=DB::transaction(function()use($d){$num='CPO-'.now()->format('ym').'-'.str_pad((string)(DB::table('customer_pos')->count()+1),4,'0',STR_PAD_LEFT);$id=DB::table('customer_pos')->insertGetId(['number'=>$num,'customer_id'=>$d['customer_id'],'sales_rep_id'=>$d['sales_rep_id'],'customer_po_reference'=>$d['customer_po_reference']??null,'po_date'=>$d['po_date'],'sale_type'=>$d['sale_type'],'status'=>'draft','total'=>0,'created_at'=>now(),'updated_at'=>now()]);$total=0;foreach($d['lines'] as $line){$a=DB::table('articles')->find($line['article_id']);$pieces=$line['sets']*$a->pieces_per_set;$value=$pieces*$a->selling_price;$total+=$value;DB::table('customer_po_lines')->insert(['customer_po_id'=>$id,'article_id'=>$a->id,'sets'=>$line['sets'],'pieces'=>$pieces,'rate'=>$a->selling_price,'line_total'=>$value,'created_at'=>now(),'updated_at'=>now()]);}DB::table('customer_pos')->where('id',$id)->update(['total'=>$total]);return DB::table('customer_pos')->find($id);});return response()->json($po,201);}
 public function convert(int $id):JsonResponse {$result=DB::transaction(function()use($id){$po=DB::table('customer_pos')->lockForUpdate()->find($id);abort_unless($po,404,'Customer PO not found.');abort_if($po->status!=='draft',422,'Only a draft customer PO can be converted.');$soNum='SO-'.now()->format('ym').'-'.str_pad((string)(DB::table('sales_orders')->count()+1),4,'0',STR_PAD_LEFT);$so=DB::table('sales_orders')->insertGetId(['number'=>$soNum,'customer_po_id'=>$id,'customer_id'=>$po->customer_id,'sales_rep_id'=>$po->sales_rep_id,'order_date'=>$po->po_date,'status'=>'confirmed','total'=>$po->total,'created_at'=>now(),'updated_at'=>now()]);$lines=DB::table('customer_po_lines')->where('customer_po_id',$id)->get();foreach($lines as $line){$sizes=DB::table('article_sizes')->where('article_id',$line->article_id)->orderBy('sort_order')->get();foreach($sizes as $size)DB::table('sales_order_size_lines')->insert(['sales_order_id'=>$so,'article_id'=>$line->article_id,'size_label'=>$size->size_label,'quantity'=>$line->sets*$size->pieces_per_set,'rate'=>$line->rate,'created_at'=>now(),'updated_at'=>now()]);}$customer=DB::table('customers')->find($po->customer_id);$invoiceNum='INV-'.now()->format('ym').'-'.str_pad((string)(DB::table('sales_invoices')->count()+1),4,'0',STR_PAD_LEFT);$due=date('Y-m-d',strtotime($po->po_date.' +'.($po->sale_type==='cash'?0:$customer->credit_days).' days'));$invoice=DB::table('sales_invoices')->insertGetId(['number'=>$invoiceNum,'sales_order_id'=>$so,'customer_id'=>$po->customer_id,'sales_rep_id'=>$po->sales_rep_id,'invoice_date'=>$po->po_date,'due_date'=>$due,'sale_type'=>$po->sale_type,'status'=>'unpaid','subtotal'=>$po->total,'discount'=>0,'tax'=>0,'total'=>$po->total,'received_amount'=>0,'outstanding'=>$po->total,'created_at'=>now(),'updated_at'=>now()]);DB::table('customer_pos')->where('id',$id)->update(['status'=>'invoiced','updated_at'=>now()]);if($po->sale_type==='cash')$this->postReceipt(['customer_id'=>$po->customer_id,'sales_rep_id'=>$po->sales_rep_id,'invoice_id'=>$invoice,'receipt_date'=>$po->po_date,'payment_method'=>'cash','reference'=>'Cash sale','amount'=>$po->total]);return ['sales_order'=>DB::table('sales_orders')->find($so),'invoice'=>DB::table('sales_invoices')->find($invoice)];});return response()->json($result,201);}
 public function receipt(Request $r):JsonResponse {$d=$r->validate(['invoice_id'=>'required|exists:sales_invoices,id','receipt_date'=>'required|date','payment_method'=>'required|in:cash,bank_transfer,cheque,card','reference'=>'nullable|max:80','amount'=>'required|numeric|gt:0']);$invoice=DB::table('sales_invoices')->find($d['invoice_id']);abort_if($d['amount']>$invoice->outstanding+0.001,422,'Receipt exceeds the invoice outstanding balance.');return response()->json(DB::transaction(fn()=>$this->postReceipt($d+['customer_id'=>$invoice->customer_id,'sales_rep_id'=>$invoice->sales_rep_id])),201);}
 private function postReceipt(array $d):array {$invoice=DB::table('sales_invoices')->lockForUpdate()->find($d['invoice_id']);$num='REC-'.now()->format('ym').'-'.str_pad((string)(DB::table('customer_receipts')->count()+1),4,'0',STR_PAD_LEFT);$rid=DB::table('customer_receipts')->insertGetId(['number'=>$num,'customer_id'=>$d['customer_id'],'sales_rep_id'=>$d['sales_rep_id'],'receipt_date'=>$d['receipt_date'],'payment_method'=>$d['payment_method'],'reference'=>$d['reference']??null,'amount'=>$d['amount'],'status'=>'posted','created_at'=>now(),'updated_at'=>now()]);$days=(int)floor((strtotime($d['receipt_date'])-strtotime($invoice->invoice_date))/86400);$base=DB::table('sales_order_size_lines as l')->join('articles as a','a.id','=','l.article_id')->where('l.sales_order_id',$invoice->sales_order_id)->selectRaw('SUM(l.quantity*a.commission_rate) base')->value('base')??0;$commission=$days<=100?round($base*($d['amount']/$invoice->total),2):0;DB::table('receipt_allocations')->insert(['receipt_id'=>$rid,'invoice_id'=>$invoice->id,'amount'=>$d['amount'],'days_taken'=>$days,'commission_amount'=>$commission,'commission_status'=>$days<=100?'eligible':'blocked_late','created_at'=>now(),'updated_at'=>now()]);$received=$invoice->received_amount+$d['amount'];$outstanding=max(0,$invoice->total-$received);DB::table('sales_invoices')->where('id',$invoice->id)->update(['received_amount'=>$received,'outstanding'=>$outstanding,'status'=>$outstanding<0.01?'paid':'part_paid','updated_at'=>now()]);return ['receipt'=>DB::table('customer_receipts')->find($rid),'commission'=>$commission,'days_taken'=>$days];}
 public function aging(Request $r):JsonResponse {$asOf=$r->validate(['as_of'=>'nullable|date'])['as_of']??now()->toDateString();$rows=DB::table('sales_invoices as i')->join('customers as c','c.id','=','i.customer_id')->join('sales_representatives as rep','rep.id','=','i.sales_rep_id')->where('i.outstanding','>',0)->whereDate('i.invoice_date','<=',$asOf)->select('i.*','c.code as customer_code','c.name as customer_name','rep.name as rep_name')->get()->map(function($x)use($asOf){$days=max(0,(int)floor((strtotime($asOf)-strtotime($x->due_date))/86400));$x->days_overdue=$days;$x->bucket=$days===0?'current':($days<=30?'1_30':($days<=60?'31_60':($days<=90?'61_90':'90_plus')));return $x;});return response()->json(['as_of'=>$asOf,'rows'=>$rows,'total'=>(float)$rows->sum('outstanding')]);}
}
